import React, {Component} from 'react';
import {Container, Collapse,ListGroup,ListGroupItem,Button} from 'reactstrap';
import {CSSTransition, TransitionGroup} from 'react-transition-group';
import { v4 as uuidv4 } from 'uuid';
import {connect} from 'react-redux';//connects component to the redux store 
import {getItems} from '../actions/itemActions';//imports the fetchPost action from the fetchPosts file defined in the  actions folder
import PropTypes from 'prop-types';


class ShoppingList extends Component {

    componentDidMount(){
        this.props.getItems();
    }
 
    render(){
        const {items} = this.props.item;
        return(
            <Container>
                <Button color="dark" style={{marginBottom:'2rem'}} onClick={ ()=>{
                    const name = prompt('Enter Item');
                    if(name){
                        this.setState(state=>({
                            items: [...state.items, {id:uuidv4(), name}]
                        }));
                    }
                }}>Add Item</Button>
                <ListGroup>
                    <TransitionGroup className="shopping-list">
                        {items.map(({id,name,})=>(
                            <CSSTransition key={id} timeout={500} classNames="fade">
                                <ListGroupItem>
                                    <Button className="remove-btn" color="danger" size="sm" onClick={()=>{this.setState(
                                        state=>({
                                            items:state.items.filter(item=>item.id!==id)        
                                        })
                                    );}}>&times;</Button>
                                    {name}
                                </ListGroupItem>
                            </CSSTransition>
                        ))}
                    </TransitionGroup>
                </ListGroup>
            </Container>
        );
    }
}

ShoppingList.propTypes={
   getItems:PropTypes.func.isRequired,
   item:PropTypes.object.isRequired 
}

const mapStateToProps = state =>({
    item: state.item  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts 
    
});
    
export default connect(mapStateToProps,{getItems})(ShoppingList);
